LABELS={'check':'Check & scan','research':'Investigate','report':'Report & share'}
ICONS={'check':'<circle cx="13" cy="13" r="8"/><path d="m19 19 7 7M9 13h8"/>','research':'<circle cx="16" cy="7" r="3"/><circle cx="6" cy="25" r="3"/><circle cx="26" cy="25" r="3"/><path d="m14 10-6 12m10-12 6 12M9 25h14"/>','report':'<path d="M7 26V5m1 1c7-5 10 5 18 0v13c-8 5-11-5-18 0"/>'}

def render(root,source_logo):
    manifest=json.loads((root/'assets/tool-logo-manifest.json').read_text())
    def logo(tool):
        record=manifest.get(tool['id'],{})
        if record.get('path'):
            b64=base64.b64encode((root/record['path']).read_bytes()).decode()
            return f'<img src="data:{record["type"]};base64,{b64}" alt="" width="32" height="32" loading="lazy" decoding="async">'
        if tool['id']=='phishtank':return source_logo('PhishTank')
        return '<svg viewBox="0 0 32 32" aria-hidden="true">'+ICONS[tool['tasks'][0]]+'</svg>'
    cards=[]
    for t in TOOLS:
        tags=''.join(f'<span>{LABELS[x]}</span>'for x in t['tasks'])
        more=f'<a href="{E(t["extra_url"],quote=True)}" target="_blank" rel="noopener noreferrer">{E(t["extra_label"])} ↗</a>'if t.get('extra_url')else''
        refs=''.join(f'<a href="{E(u,quote=True)}" target="_blank" rel="noopener noreferrer">{E('Access & plans' if any(k in u for k in ['pricing','plans','signup','login_required']) else 'Service documentation' if any(k in u for k in ['docs.','/docs/','knowledge.','faq']) else 'Official service')} ↗</a>'for i,u in enumerate(t['references']))
        cards.append(f'''<article class="community-tool" id="tool-{t['id']}" data-tool-tasks="{' '.join(t['tasks'])}" data-tool-search="{E((t['name']+' '+t['description']).lower(),quote=True)}"><div class="tool-card-top"><span class="tool-identity">{logo(t)}</span><div class="tool-tags">{tags}</div></div><h3><a href="{E(t['url'],quote=True)}" target="_blank" rel="noopener noreferrer">{E(t['name'])}</a></h3><p>{E(t['description'])}</p><div class="tool-card-bottom"><span class="tool-access">{E(t['access'])}</span><a class="tool-action" href="{E(t['url'],quote=True)}" target="_blank" rel="noopener noreferrer">{E(t['action'])} <span>↗</span></a>{more}</div><details class="tool-details"><summary>Access & context</summary><p>{E(t['note'])}</p><div>{refs}</div></details></article>''')
    buttons='<button type="button" data-tool-filter="all" aria-pressed="true"><span class="tool-filter-icon">↗</span><span>All tools<small>Every way to contribute</small></span></button>'
    for key,title,subtitle in [('check','Check a link','Look for a second signal'),('research','Investigate','Understand the evidence'),('report','Report & share','Help the next person')]:
        buttons+=f'<button type="button" data-tool-filter="{key}" aria-pressed="false"><svg viewBox="0 0 32 32" aria-hidden="true">{ICONS[key]}</svg><span>{title}<small>{subtitle}</small></span></button>'
    return '''<section id="community-tools" class="community-tools section" aria-labelledby="tools-title"><div class="wrap"><div class="section-heading"><div><div class="eyebrow">THE SAME FIGHT. MORE WAYS TO HELP.</div><h2 id="tools-title">Check a link.<br><em>Share a signal.</em></h2></div><div class="tools-introduction"><p>Public scanners, research tools and reporting channels help turn a suspicion into evidence — and evidence into a signal that other defenders can act on.</p><p>We use these services in our own work. They deserve recognition alongside the people and lists that inform it.</p></div></div>
<div class="tools-manifesto"><span class="tools-ripple" aria-hidden="true"><i></i><i></i><i></i><b>↗</b></span><div><h3>You do not need to own a security platform to contribute.</h3><p>Many basic checks and reporting routes are free and work without registration. Others use free accounts or have limits. A careful check, a useful report or a piece of evidence can help someone beyond your own screen.</p></div></div>
<div class="tool-filters" role="group" aria-label="Choose a tool by task">'''+buttons+'''</div><div class="tool-directory-bar"><p id="tool-count" role="status" aria-live="polite">21 services · A–Z</p><div class="tool-directory-options"><button id="reset-tools" class="clear-directory" type="button" hidden>Clear filters ×</button><label class="tool-search"><span class="sr-only">Find a community tool</span><span aria-hidden="true">⌕</span><input type="search" id="tool-search" placeholder="Find a tool…" autocomplete="off"></label></div></div><div class="community-tool-grid" id="tool-grid">'''+''.join(cards)+'''</div><p id="tool-empty" class="empty" hidden>No matching tools. Try another name or choose all tools.</p>
<div class="directory-controls" id="tool-pagination" hidden><p>Alphabetical, without ranking. Search and task filters cover every service.</p><button id="show-tools" class="directory-expand" type="button" aria-controls="tool-grid" aria-expanded="false">Show all 21 services ↓</button></div><div class="tools-footnote"><div><h3>One purpose. An open-ended effort.</h3><p>This directory, like the source list, is a starting point. Many more tools, researchers and communities contribute. We share the goal of reducing phishing harm; there is no leaderboard for that work.</p><a class="suggest-resource" href="https://github.com/phishdestroy/destroylist/issues/new" target="_blank" rel="noopener noreferrer">Suggest a resource or correction ↗</a></div><div><p>Links credit independently operated services; they do not imply a partnership or configured data ingestion. Free access refers to the stated basic function, not every product or API.</p><p>Public scans can make submitted URLs visible to others. Check visibility before sharing links with personal data or access tokens. A clean result is not a guarantee, and a report is not a confirmed takedown.</p><a href="../tools.json">Tool directory & access references <span>JSON ↗</span></a></div></div></div></section>'''

def reference_text():
    return '\n## Community tools: check, investigate and report\n\nThe maintainers use these independently operated services in their work and credit them alongside data sources. This is an open-ended directory, not a ranking, partnership list or list of configured upstream feeds. Many basic functions are free without registration; some use free accounts, quotas or paid plans. Public scans can expose submitted URLs. Check visibility before sharing sensitive links.\n\n'+'\n'.join('### '+t['name']+'\n'+t['description']+'\nAccess: '+t['access']+'. '+t['note']+'\n'+t['url']+ ('\n'+t['extra_url']if t.get('extra_url')else'')+'\n'for t in TOOLS)

def write_registry(root,base):
    data={'name':'Community phishing investigation and reporting tools','canonical_url':base+'#community-tools','reviewed_at':date.today().isoformat(),'scope':'Tools the maintainers use, credited independently from configured data feeds. Non-exhaustive; not a ranking or partnership list.','access_notes':'Many basic web functions are free without registration. Account requirements, quotas and paid features differ by provider. See each service and its references.','visibility_notes':'Public scans may expose submitted URLs. A clean verdict is not a guarantee; reporting does not guarantee blocking or removal.','tools':TOOLS}
    (root/'dist/tools.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')